  probes: [['PE26006', '29 Jul 2026', 'Open', 'Front lower lateral link detachment, MY2018–2020 Model 3 and MY2021–2023 Model Y; 156 complaints; possible loss of directional control; listed open in NHTSA’s file on 18 Nov. Not a recall.', 'https://static.nhtsa.gov/odi/inv/2026/INOA-PE26006-16559.pdf'], ['EA26002', '18 Mar 2026', 'Open', 'FSD collisions in reduced roadway visibility; 3,203,754 vehicles; 9 incidents, 1 fatality. Upgraded from PE24031.', U.nhtsa], ['Cybercab certification (AQ26002)', 'Sep 2026', 'Open', 'Special Order (21 requests): Tesla to explain under oath, by 30 Oct, how a car with no steering wheel or pedals was certified. Answers not in NHTSA’s public file as of 30 Oct; no finding announced.', U.cabhwy], ['FMVSS 108 proposal', '23 Oct 2026', 'Proposed rule', 'Not a probe: NHTSA proposes optional cyan ADS marker lamps and drops manual lighting-control requirements for driverless vehicles (relevant to Cybercab).', U.fmvss108], ['Defect petition', '23 Sep 2026', 'Under evaluation', 'Petition alleging that MY2026 Robotaxis (Model Y and Cybercab) with the automated driving system engaged exceed posted speed limits in active school zones; about 1,000 vehicles.', U.schoolzone]],
